package com.didww.sdk.resource.smstrunkconfiguration;

import com.didww.sdk.internal.Redact;
import com.fasterxml.jackson.annotation.JsonIgnore;
import com.fasterxml.jackson.annotation.JsonProperty;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.Setter;

import java.util.List;

/**
 * Outbound messages are submitted to DIDWW over HTTP. The submit URL is returned in the trunk meta
 * ({@link com.didww.sdk.resource.SmsTrunk#getMetaHost()}). {@code authName} and {@code authPassword} are
 * generated by DIDWW and are never sent in a request.
 */
@Getter
@Setter
public class HttpOutConfiguration extends SmsTrunkConfiguration {

    /** URL the status events of messages submitted through the trunk are sent to. */
    @JsonProperty("callback_url")
    private String callbackUrl;

    /** Addresses messages are accepted from. */
    @JsonProperty("allowed_ips")
    private List<String> allowedIps;

    /** Generated HTTP username. Read-only. */
    @Setter(AccessLevel.NONE)
    @JsonProperty(value = "auth_name", access = JsonProperty.Access.WRITE_ONLY)
    private String authName;

    /** Generated HTTP password. Read-only. */
    @Setter(AccessLevel.NONE)
    @JsonProperty(value = "auth_password", access = JsonProperty.Access.WRITE_ONLY)
    private String authPassword;

    @Override
    @JsonIgnore
    public String getType() {
        return "http_out";
    }

    /**
     * Masks the generated credentials. The wire payload is unaffected.
     */
    @Override
    public String toString() {
        return "HttpOutConfiguration("
                + "callbackUrl=" + callbackUrl
                + ", allowedIps=" + allowedIps
                + ", authName=" + Redact.mask(authName)
                + ", authPassword=" + Redact.mask(authPassword)
                + ")";
    }
}
